package org.apache.commons.math.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.linear.InvalidMatrixException;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for SingularValueDecompositionImpl.getU()
 * Focuses on maximizing branch and line coverage.
 */
public class SingularValueDecompositionImpl_getU_TriageGen0Test {

    /**
     * Test Case 1: m >= n (The first branch of the if-else logic within the null check)
     * This covers the logic where the tridiagonal matrix is Bt.B.
     * It exercises the loop for i < n-1 and the loop for i == n-1.
     */
    @Test
    public void testGetU_M_Greater_Than_N() throws InvalidMatrixException {
        // Create a simple 3x2 matrix (m=3, n=2)
        // m >= n is true.
        double[][] data = {
            {1.0, 0.0},
            {0.0, 1.0},
            {1.0, 1.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);

        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u = svd.getU();

        assertNotNull("U matrix should not be null", u);
        assertEquals("U matrix rows should match m", 3, u.getRowDimension());
        assertEquals("U matrix columns should match n", 2, u.getColumnDimension());

        // Verify caching: calling second time should return same instance (or at least same values)
        RealMatrix uCached = svd.getU();
        assertEquals("Cached U should be the same as first U", u, uCached);
    }






}

